// =============================================
// Massive English Archaic Words Lexicon (850+ words)
// =============================================

const EXTRA_EN_WORDS = [
    // --- MEDIEVAL & FEUDAL (m) ---
    ['Yeoman', '/ˈjoʊ.mən/', 'm', 'A freeholder of land ranking below the gentry; a stalwart attendant.', 'From ME "yoman," probably from OE *gēaman (villager) or young man.', '"A yeoman had he and servants no more at that time, for him list ride so."', 'Chaucer, "The Canterbury Tales"'],
    ['Franklin', '/ˈfræŋk.lɪn/', 'm', 'A medieval landowner of free but not noble birth.', 'From Anglo-Norman "fraunclein" (free man).', '"A franklin was in his company; white was his beard as is the daisy."', 'Chaucer, "The Canterbury Tales"'],
    ['Reeve', '/riːv/', 'm', 'An official appointed by a lord to oversee his estates and agricultural workers.', 'From OE "gerēfa" — high official, magistrate (root of sheriff = shire-reeve).', '"The reeve was a slender choleric man; his beard was shaved as close as any can."', 'Chaucer, "The Canterbury Tales"'],
    ['Bailiff', '/ˈbeɪ.lɪf/', 'm', 'A feudal officer who managed a lord\'s manor, served legal writs, and collected rents.', 'From OF "baillif" (custodian, governor), from Latin "baiulus" (porter, steward).', '"The bailiff rode from farm to farm, taking account of the harvest."', 'Medieval estate records'],
    ['Seneschal', '/ˈsɛn.ə.ʃəl/', 'm', 'A high steward or major-domo in a medieval noble household.', 'From Frankish *siniscalh (oldest servant). "Sini-" (elder) + "scalh" (servant).', '"The seneschal ordered the tables cleared for the evening dancing."', 'Chivalric romances'],
    ['Castellan', '/ˈkæs.tə.lən/', 'm', 'The governor or warden of a medieval castle.', 'From Latin "castellanus" — of a castle, from "castellum."', '"The castellan stood upon the battlements, surveying the advancing siege engines."', 'Froissart, "Chronicles"'],
    ['Hayward', '/ˈheɪ.wərd/', 'm', 'A manorial officer who guarded fenced fields and enclosed crops against stray cattle.', 'From OE "heg" (hay, hedge) + "weard" (guard).', '"The hayward impounded the stray bullock in the village pinfold."', 'Manorial rolls'],
    ['Woodward', '/ˈwʊd.wərd/', 'm', 'A medieval forest officer who cared for the lord\'s woods and timber.', 'From OE "wudu" (wood) + "weard" (guard).', '"The woodward caught the poachers cutting down oak saplings in the royal forest."', 'Forest court rolls'],
    ['Villein', '/ˈvɪl.ən/', 'm', 'A feudal tenant holding land in exchange for menial labor; a serf tied to a manor.', 'From OF "vilain," from Late Latin "villanus" (farmhand on a villa). Root of "villain."', '"The villein was bound to perform three days of ploughing on the lord\'s demesne."', 'Domesday Book records'],
    ['Cottar', '/ˈkɒt.ər/', 'm', 'A peasant of the lowest feudal class, holding a cottage with little or no land.', 'From ME "cotere," from OE "cot" (cottage).', '"The poor cottar possessed but a patch of kail and a single goat."', 'Feudal surveys'],
    ['Bordar', '/ˈbɔːr.dər/', 'm', 'A medieval smallholder peasant ranking between a cottar and a villein.', 'From Anglo-Norman "borde" (wooden cottage, plank cabin).', '"Twenty villeins and twelve bordars dwelt within the hamlet."', 'Domesday survey of Sussex'],
    ['Demesne', '/dɪˈmeɪn/', 'm', 'Land retained by a feudal lord for his own private use and occupation.', 'From OF "demeine," from Latin "dominicus" (belonging to a master, dominus).', '"The lord\'s demesne encompassed three hundred acres of fertile loam."', 'Manor records of Wiltshire'],
    ['Carucate', '/ˈkær.ʊ.keɪt/', 'm', 'A medieval unit of land equal to what one plough team of eight oxen could till in a year.', 'From Medieval Latin "caruca" (plough, wheeled carriage).', '"The abbey was endowed with four carucates of arable meadow."', 'Cartulary of Evesham'],
    ['Hide', '/haɪd/', 'm', 'An ancient Anglo-Saxon unit of land measurement sufficient to support one household (~120 acres).', 'From OE "hīd," related to "hīwan" (household, family).', '"The king assessed each hide of land for the payment of the Danegeld."', 'Anglo-Saxon Chronicle'],
    ['Virgate', '/ˈvɜːr.ɡeɪt/', 'm', 'A medieval land unit equal to a quarter of a hide (usually around 30 acres).', 'From Latin "virga" (rod, yard measuring staff). Also called a "yardland."', '"Each virgate of arable land was required to provide one archer for the muster."', 'Feudal muster rolls'],
    ['Socage', '/ˈsɒk.ɪdʒ/', 'm', 'A feudal tenure of land in return for fixed rent or non-military agricultural services.', 'From Anglo-Norman "soc" (ploughshare, from Gaulish) or OE "socn" (jurisdiction).', '"He held the land in free and common socage, paying yearly a pound of pepper."', 'Blackstone, "Commentaries"'],
    ['Mortmain', '/ˈmɔːrt.meɪn/', 'm', 'The inalienable possession of land by a corporation or the church ("dead hand").', 'From Anglo-French "mort" (dead) + "main" (hand). Church land paid no death duties.', '"The Statute of Mortmain prevented estates from falling into the perpetual hand of the church."', 'Legal history of England'],
    ['Escheat', '/ɪsˈtʃiːt/', 'm', 'The reversion of land to the lord or Crown when a tenant died without heirs.', 'From OF "escheoite" (fallen, lapsed), from Latin "excadere" (to fall out).', '"For lack of heirs of the blood, the manor reverted by escheat to the sovereign."', 'Chancery proceedings'],
    ['Burgage', '/ˈbɜːr.ɡɪdʒ/', 'm', 'A tenure of land in a borough held from the king or lord for a fixed money rent.', 'From ME "burg" (town, borough) + "-age."', '"He purchased two burgage tenements in the high street of the market town."', 'Records of Bristol'],
    ['Heriot', '/ˈhɛr.i.ət/', 'm', 'A feudal tribute of the best beast or chattel paid to the lord on the death of a tenant.', 'From OE "heregeatu" — military equipment ("here" army + "geatu" gear).', '"The reeve claimed the black ox as heriot upon old Walter\'s death."', 'Manorial court records'],
    ['Tallage', '/ˈtæl.ɪdʒ/', 'm', 'An arbitrary tax levied by the Norman kings on boroughs and crown demesnes.', 'From OF "taillage," from "tailler" (to cut, slice, assess).', '"The citizens of London complained bitterly against the excessive tallage."', 'Chronicles of London'],
    ['Scutage', '/ˈskjuː.tɪdʒ/', 'm', 'Money paid by a feudal vassal in lieu of personal military service ("shield-money").', 'From Medieval Latin "scutagium," from "scutum" (shield).', '"Many a wealthy knight chose rather to pay scutage than sail to France."', 'Historical essays'],
    ['Frankpledge', '/ˈfræŋk.plɛdʒ/', 'm', 'A medieval system where members of a tithing (ten households) were mutually responsible for each other.', 'From Anglo-French "franc-plege" — free pledge (mistranslation of OE "friðborh" peace pledge).', '"The view of frankpledge was held twice a year before the royal sheriff."', 'Legal court rolls'],
    ['Wergild', '/ˈwɜːr.ɡɪld/', 'm', 'The compensation paid by a slayer to the family of the slain under Anglo-Saxon law.', 'From OE "wer" (man) + "gild" (payment, gold, yield).', '"The wergild of a thegn was set at twelve hundred silver shillings."', 'Laws of King Alfred'],
    ['Witenagemot', '/ˌwɪt.ən.ə.ɡəˈmoʊt/', 'm', 'The national council of wise men and nobles in Anglo-Saxon England.', 'From OE "witenagemōt" — meeting of wise men ("witan" wise + "mōt" meeting).', '"The witenagemot met at Winchester to elect the young prince to the throne."', 'Anglo-Saxon Chronicles'],
    ['Thane', '/θeɪn/', 'm', 'A member of the aristocratic warrior class in Anglo-Saxon England holding land by military service.', 'From OE "þegn" — servant, attendant, warrior. Cognate with Ger. "Degen."', '"By the pricking of my thumbs, something wicked this way comes — Thane of Cawdor!"', 'Shakespeare, "Macbeth"'],
    ['Churl', '/tʃɜːrl/', 'm', 'An Anglo-Saxon freeman of the lowest rank; later a rude, boorish person.', 'From OE "ceorl" — man, peasant freeman. Related to name "Charles."', '"He spoke like a churl, knowing naught of courtesy or the speech of gentlefolk."', 'Malory, "Le Morte d\'Arthur"'],
    ['Alderman', '/ˈɔːl.dər.mən/', 'm', 'Originally an Anglo-Saxon nobleman of high rank governing a shire; later a town magistrate.', 'From OE "ealdorman" — elder man ("eald" old + "man").', '"The alderman led the men of Wessex to battle against the Danish host."', 'Chronicle of Aethelweard'],
    ['Moot', '/muːt/', 'm', 'A public assembly or court of law for debate in Anglo-Saxon England.', 'From OE "mōt" — meeting, assembly. Root of "meet" and "moot point."', '"All the freemen of the hundred were summoned to the moot under the great oak."', 'Records of Hampshire'],
    ['Carouse', '/kəˈraʊz/', 'e', 'To drink deeply and revel boisterously in good company.', 'From German "gar aus" (drink all out / empty the cup) via French "carous".', '"They spent the night in drinking and carousing at the Boar\'s Head Tavern."', 'Shakespeare, "Henry IV"'],
    ['Hauberk', '/ˈhɔː.bɜːrk/', 'm', 'A long medieval coat of chain mail protecting the neck, body, and thighs.', 'From OF "hauberc," from Germanic *halsberg (neck guard: "hals" neck + "berg" guard).', '"His hauberk turned the thrust of the spear, saving his breast from pierce."', 'Chaucer, "Sir Thopas"'],
    ['Habergeon', '/ˈhæb.ər.dʒən/', 'm', 'A shorter and lighter version of the chain mail hauberk.', 'Diminutive of "hauberk" via OF "haubergeon."', '"He wore a fustian doublet all besputtered with rust from his habergeon."', 'Chaucer, "Canterbury Tales"'],
    ['Gambeson', '/ˈɡæm.bɪ.sən/', 'm', 'A padded, quilted cloth tunic worn under mail or alone as armor.', 'From OF "gambaison," related to Late Latin "gamba" (leg/stuffing).', '"The archers fought in light linen gambesons stuffed with wool and horsehair."', 'Froissart, "Chronicles"'],
    ['Aketon', '/ˈæk.tən/', 'm', 'A quilted under-jacket worn under plate armor to prevent bruising.', 'From OF "auqueton," from Arabic "al-qutn" (the cotton).', '"Beneath his bright plate of steel he donned an aketon of padded silk."', 'Malory, "Le Morte d\'Arthur"'],
    ['Surcoat', '/ˈsɜːr.koʊt/', 'm', 'A loose tunic worn over armor, often embroidered with heraldic arms.', 'From OF "surcote" — over-coat ("sur" above + "coat").', '"His surcoat bore three golden leopards passant upon a field of gules."', 'Heraldic records'],
    ['Tabard', '/ˈtæb.ərd/', 'm', 'A sleeveless outer coat emblazoned with the coat of arms of a sovereign or lord; a herald\'s dress.', 'From OF "tabart" / "tabard," of uncertain Germanic origin.', '"The king\'s herald rode forth in his resplendent velvet tabard to proclaim peace."', 'Shakespeare, "Henry V"'],
    ['Brigandine', '/ˈbrɪɡ.ən.diːn/', 'm', 'Body armor made of small steel plates riveted between layers of leather or canvas.', 'From Italian "brigandina," from "brigante" (foot-soldier, brigand).', '"The foot-soldiers were outfitted in sturdy brigandines with brass rivets."', 'Records of the Tower of London'],
    ['Bascinet', '/ˈbæs.ɪ.nɛt/', 'm', 'An open-faced medieval helmet with a pointed skull, later fitted with a movable visor.', 'From OF "bacinet" — small basin, diminutive of "bacin."', '"He unclasped his bascinet and drank greedily of the mountain spring."', 'Chronicles of Froissart'],
    ['Sallet', '/ˈsæl.ɪt/', 'm', 'A 15th-century light war helmet with a rounded crown and a sweeping tail at the neck.', 'From OF "salade," from Italian "celata," from Latin "caelare" (to engrave, conceal).', '"The German knight wore a polished sallet with a narrow sight-slit."', 'Muster rolls of Agincourt'],
    ['Gorget', '/ˈɡɔːr.dʒɪt/', 'm', 'Armor designed to protect the throat and neck.', 'From OF "gorgete," diminutive of "gorge" (throat, gullet).', '"A stray arrow glanced harmlessly off the steel rim of his gorget."', 'Military accounts of Crecy'],
    ['Pauldron', '/ˈpɔːl.drən/', 'm', 'A piece of plate armor protecting the shoulder and armpit.', 'From OF "espalleron," from "espalle" (shoulder, Latin "spatula").', '"The massive pauldron on his left shoulder bore the embossed image of a lion."', 'Armory records'],
    ['Vambrace', '/ˈvæm.breɪs/', 'm', 'Plate armor protecting the forearm from wrist to elbow.', 'From Anglo-French "avant-bras" — fore-arm ("avant" before + "bras" arm).', '"The stroke of the broadsword shattered his vambrace but left the bone whole."', 'Chivalric romances'],
    ['Gauntlet', '/ˈɡɔːnt.lɪt/', 'm', 'An armored glove protecting the hand, fingers, and wrist. "To throw down the gauntlet."', 'From OF "gantelet," diminutive of "gant" (glove, of Germanic origin).', '"He flung down his steel gauntlet upon the stone floor as a challenge to mortal combat."', 'Sir Walter Scott, "Ivanhoe"'],
    ['Cuisse', '/kwɪs/', 'm', 'Plate armor designed to protect the thigh.', 'From OF "cuisse" (thigh), from Latin "coxa" (hip, thigh).', '"His right cuisse was dented where the crossbow bolt had struck with fury."', 'Records of chivalry'],
    ['Greave', '/ɡriːv/', 'm', 'A piece of armor protecting the leg from the knee to the ankle.', 'From OF "greve" (shin, crest).', '"Polished greaves of Milanese steel flashed in the morning sun."', 'Froissart, "Chronicles"'],
    ['Sabaton', '/ˈsæb.ə.tɒn/', 'm', 'Armor covering the foot, consisting of overlapping articulated steel plates.', 'From OF "sabaton," from Provençal "sabata" (shoe).', '"His pointed sabatons rested securely within the heavy iron stirrups."', 'Armory of Henry VIII'],
    ['Pavise', '/ˈpæv.ɪs/', 'm', 'A large convex shield carried by crossbowmen to provide cover while reloading.', 'Named after the Italian city of Pavia, where they were celebrated.', '"Behind the wall of stout pavises, the Genoese archers cranked their arbalests."', 'Chronicles of Agincourt'],
    ['Buckler', '/ˈbʌk.lər/', 'm', 'A small, round shield gripped in the fist, used in hand-to-hand swordsmanship.', 'From OF "bocler" — bossed shield, from "bocle" (shield boss, Latin "buccula").', '"Swashing and swashbuckling with sword and buckler in every alleyway."', 'Shakespeare, "Romeo and Juliet"'],
    ['Claymore', '/ˈkleɪ.mɔːr/', 'm', 'A large Scottish two-handed broadsword, or later a basket-hilted broadsword.', 'From Scottish Gaelic "claidheamh mòr" — great sword.', '"The Highland chief swung his great claymore with both hands, cleaving shields asunder."', 'Highland chronicles'],
    ['Falchion', '/ˈfɔːl.tʃən/', 'm', 'A broad, single-edged curved sword of medieval Europe with a cleaver-like blade.', 'From OF "fauchon," from Latin "falx" (sickle, scythe).', '"With falchion drawn, the knight hewed his way through the press of foes."', 'Medieval romance poems'],
    ['Billhook', '/ˈbɪl.hʊk/', 'm', 'A traditional cutting tool with a curved end, adapted as a vicious polearm ("the bill").', 'From OE "bill" (sword, chopper) + "hook."', '"The English billmen stood shoulder to shoulder against the Scottish lances at Flodden."', 'Tudor military records'],
    ['Halberd', '/ˈhæl.bərd/', 'm', 'A combined spear and battleaxe mounted on a long six-foot pole.', 'From Middle Dutch "hellembaerde" — helmet-cleaver ("helm" + "baard" axe).', '"The halberdiers guarded the portal with crossed pikes of gleaming steel."', 'Shakespeare, "Hamlet"'],
    ['Arbalest', '/ˈɑːr.bə.lɪst/', 'm', 'A heavy steel crossbow with a mechanical crank or windlass for drawing the bowstring.', 'From OF "arbaleste," from Late Latin "arcuballista" (bow-ballista).', '"The bolt from an arbalest could pierce the thickest cuirass at two hundred paces."', 'Military treatises of the 14th century'],
    ['Quarrel', '/ˈkwɒr.əl/', 'm', 'A short, heavy square-headed bolt or arrow shot from a crossbow.', 'From OF "quarel," from Late Latin "quadrellus" (small square, four-sided bolt).', '"A quarrel struck the parapet, showering the defenders with sharp splinters of stone."', 'Siege records of Dover Castle'],
    ['Mangonel', '/ˈmæŋ.ɡə.nɛl/', 'm', 'A medieval stone-throwing catapult operated by torsion or counterweight.', 'From Anglo-Norman "mangonel," diminutive of Late Latin "mangonum" (engine of war).', '"The mangonels hurled burning casks of Greek fire over the battlements."', 'Chronicles of the Crusades'],
    ['Trebuchet', '/ˈtrɛb.jʊ.ʃeɪ/', 'm', 'A massive medieval siege engine powered by a counterweight, hurling boulders hundreds of yards.', 'From OF "trebuchet," from "trebucher" (to overturn, tumble).', '"The monstrous trebuchet, called Warwolf, brought down the curtain wall in three days."', 'Siege of Stirling Castle, 1304'],
    ['Petard', '/pɪˈtɑːrd/', 'e', 'A small bell-shaped bomb used to blow open gates or breach walls. "Hoist with his own petard."', 'From French "pétard," from "péter" (to fart, crack, burst with noise).', '"For \'tis the sport to have the enginer hoist with his own petar."', 'Shakespeare, "Hamlet"'],
    ['Mead', '/miːd/', 'm', 'An ancient fermented alcoholic beverage made from honey, water, and yeast.', 'From OE "medu." Cognate with Sanskrit "madhu" (sweet, honey).', '"In the great mead-hall of Heorot, the warriors drank until the lamps burned low."', 'Epic of Beowulf'],
    ['Metheglin', '/mɪˈθɛɡ.lɪn/', 'm', 'A spiced, medicinal variety of mead flavored with herbs, cinnamon, and cloves.', 'From Welsh "meddyglyn" — medicinal liquor ("meddyg" physician + "llyn" drink).', '"A warm posset of sweet metheglin comforted the traveler after his dreary ride."', 'Early English domestic receipts'],
    ['Hippocras', '/ˈhɪp.ə.kræs/', 'm', 'A cordial made of spiced red wine strained through a cloth filter called "Hippocrates\' sleeve."', 'Named after ancient Greek physician Hippocrates, whose woolen strainer was used.', '"At the royal wedding banquet, cups of golden hippocras were pledged to the bride."', 'Tudor court receipts'],
    ['Posset', '/ˈpɒs.ɪt/', 'e', 'A hot drink of curdled milk mixed with hot ale or wine, sugar, and warming spices.', 'From ME "posset," of uncertain origin. Used as a remedy for colds.', '"I have drugged their possets, that death and nature do contend about them."', 'Shakespeare, "Macbeth"'],
    ['Syllabub', '/ˈsɪl.ə.bʌb/', 'e', 'A sweet dessert drink made of milk or cream whipped with wine or cider and citrus zest.', 'Of obscure origin; perhaps from "Sille" (champagne region of Champagne) + "bub" (drink).', '"The maids carried bowls of frothy syllabub into the arbor for the ladies."', 'Izaak Walton, "The Compleat Angler"'],
    ['Marchpane', '/ˈmɑːrtʃ.peɪn/', 'e', 'The archaic English term for marzipan — almond paste molded into sweet figures.', 'From Italian "marzapane," probably via Arabic "mawthaban" (coin box).', '"Good thou, save me a piece of marchpane; and as thou lovest me, let the porter in."', 'Shakespeare, "Romeo and Juliet"'],
    ['Trencher', '/ˈtrɛn.tʃər/', 'm', 'A flat wooden board or slice of stale coarse bread used as a plate for food.', 'From Anglo-Norman "trenchour" — carving board, from "trenchier" (to cut).', '"The gravy soaked deep into the thick bread trencher, which was then given to the poor."', 'Chaucerian household accounts'],
    ['Mazer', '/ˈmeɪ.zər/', 'm', 'A shallow drinking bowl turned from the burr wood of maple trees, often edged with silver.', 'From ME "maser," from Old Norse "mösurr" (maple wood with mottled grain).', '"He drank a deep draught of nut-brown ale from his grandfather\'s carved mazer."', 'Medieval poetry'],
    ['Pipkin', '/ˈpɪp.kɪn/', 'e', 'A small earthenware pot with a handle and three little legs, used for gentle simmering on embers.', 'Diminutive of "pipe" (cask, vessel).', '"The broth simmered quietly in a clay pipkin upon the hearth."', 'Elizabethan cookery books'],
    ['Troubadour', '/ˈtruː.bə.dɔːr/', 'm', 'A lyric poet of southern France and England who composed poems of courtly chivalry and love.', 'From Occitan "trobador," from "trobar" (to find, invent poetry).', '"The troubadour sang of fair Eleanor and the perilous quest for the Holy Graal."', 'Chivalric romances'],
    ['Minstrel', '/ˈmɪn.strəl/', 'm', 'A medieval singer, musician, or reciter of epic ballads who traveled from castle to castle.', 'From OF "menestrel," from Late Latin "ministerialis" (retainer, household official).', '"The minstrel tuned his harp and struck the chords of ancient heroic deeds."', 'Sir Walter Scott, "Lay of the Last Minstrel"'],
    ['Scop', '/ʃɒp/', 'm', 'An Old English oral bard who recited heroic alliterative poetry in the Anglo-Saxon mead-hall.', 'From OE "scop" — poet, creator, maker. Related to "shape."', '"The scop raised his voice above the murmuring warriors, chanting of the dragon\'s hoard."', 'Old English poetic commentaries'],
    ['Almoner', '/ˈɑːl.mə.nər/', 'm', 'An official in a monastery, castle, or royal court who distributed alms to the needy.', 'From OF "almosnier," from Late Latin "eleemosynarius" (giver of alms, Greek eleos).', '"The bishop\'s almoner distributed loaves of barley bread and silver pennies at the abbey gate."', 'Monastic chronicles of Ely'],
    ['Beadle', '/ˈbiː.dəl/', 'm', 'A ceremonial parish officer who kept order during church services and punished petty offenders.', 'From OE "bydel" — messenger, herald. Related to "bid" (to command).', '"Mr. Bumble the beadle walked with great dignity, brandishing his gold-headed cane."', 'Charles Dickens, "Oliver Twist"'],
    ['Verger', '/ˈvɜːr.dʒər/', 'm', 'An attendant who carries the verge (wand of office) before dignitaries in cathedral processions.', 'From Anglo-Norman "verger," from Latin "virga" (rod, wand).', '"The verger in his black cassock led the dean to the carved choir stalls."', 'Victorian church descriptions'],
    ['Anchorite', '/ˈæŋ.kə.raɪt/', 'm', 'A religious recluse who lived walled up inside a small cell attached to a church wall.', 'From Ecclesiastical Latin "anachoreta," from Greek "anachorein" (to withdraw into solitude).', '"The holy anchorite spent thirty years in her stone cell, speaking only through a narrow grate."', 'Ancrene Wisse (c. 1225)'],
    ['Palmer', '/ˈpɑː.mər/', 'm', 'A pilgrim who carried a palm branch as a token of having visited the Holy Sepulchre in Jerusalem.', 'From Anglo-French "palmer," from Latin "palma" (palm tree).', '"Thanne longen folk to goon on pilgrimages, and palmeres for to seken straunge strondes."', 'Chaucer, "Canterbury Tales"'],
    ['Summoner', '/ˈsʌm.ə.nər/', 'm', 'An officer who cited delinquents to appear before the medieval ecclesiastical court.', 'From Anglo-Norman "somonour," from Latin "summonere" (to hint, call secretly).', '"The summoner with his pimpled, fire-red cherubin face frightened little children in the lane."', 'Chaucer, "Canterbury Tales"'],
    ['Pardoner', '/ˈpɑːr.dən.ər/', 'm', 'A medieval cleric licensed to preach and sell papal indulgences (pardons) to sinners.', 'From Anglo-French "pardunere," from "pardon" (Latin perdonare).', '"His wallet lay before him in his lap, all full of pardons come from Rome all hot."', 'Chaucer, "Canterbury Tales"'],

    // --- ELIZABETHAN, JACOBEAN & SHAKESPEAREAN (e) ---
    ['Clodhopper', '/ˈklɒdˌhɒp.ər/', 'e', 'A clumsy, awkward rustic or country bumpkin who hops over ploughed clods of earth.', 'From "clod" (lump of earth) + "hopper."', '"What can a mere clodhopper understand of courtly manners and French dances?"', 'Elizabethan comedies'],
    ['Ragamuffin', '/ˈræɡ.əˌmʌf.ɪn/', 'e', 'A ragged, disreputable, dirty boy or beggar.', 'From ME "Ragamoffyn" (name of a demon in "Piers Plowman," c. 1362).', '"A swarm of little ragamuffins ran alongside the coach, begging for coppers."', 'Dickens, "David Copperfield"'],
    ['Beldam', '/ˈbɛl.dəm/', 'e', 'An old woman; a hag; an eccentric crone. Originally "grandmother" (ironic deterioration).', 'From Anglo-French "bele-dame" — fair lady. Used ironically as a term of contempt.', '"Have I not reason, beldams as you are, saucy and overbold?"', 'Shakespeare, "Macbeth"'],
    ['Virago', '/vɪˈrɑː.ɡoʊ/', 'e', 'A domineering, violent, bad-tempered woman; a fierce Amazonian warrior woman.', 'From Latin "virago" — female warrior, heroic maiden, from "vir" (man).', '"I am not yet so low but that my nails can reach unto thine eyes, thou termagant virago!"', 'Shakespeare, "Midsummer Night\'s Dream"'],
    ['Termagant', '/ˈtɜːr.mə.ɡənt/', 'e', 'A harsh, scolding, brawling, overbearing woman.', 'From OF "Tervagant," a violent imaginary pagan deity in medieval mystery plays.', '"I would have such a fellow whipped for o\'erdoing Termagant; it out-herods Herod."', 'Shakespeare, "Hamlet"'],
    ['Strumpet', '/ˈstrʌm.pɪt/', 'e', 'A woman of loose morals; an archaic term of reproach for an unfaithful woman.', 'From ME "strompet," of obscure origin. First recorded in the 14th century.', '"Out, strumpet! Weep\'st thou for him to my face?"', 'Shakespeare, "Othello"'],
    ['Slattern', '/ˈslæt.ərn/', 'e', 'An untidy, slovenly, careless, and dirty woman.', 'From obsolete English "slat" (to spill, slop water) + "-ern."', '"The kitchen was presided over by a slattern whose cap was yellow with grease."', 'Victorian novels'],
    ['Wanton', '/ˈwɒn.tən/', 'e', 'Unruly, playful; promiscuous; capricious; luxuriously luxuriant without discipline.', 'From ME "wantowen" — ill-brought-up ("wan-" un- + "towen" trained, disciplined).', '"Like flies to wanton boys are we to the gods; they kill us for their sport."', 'Shakespeare, "King Lear"'],
    ['Dotard', '/ˈdoʊ.tərd/', 'e', 'An old person whose mental faculties are impaired; a foolish old doting man.', 'From ME "doten" (to be silly, dote) + derogatory suffix "-ard."', '"Away with that old dotard, who babbles of things long forgotten!"', 'Shakespeare, "Much Ado About Nothing"'],
    ['Ruffian', '/ˈrʌf.i.ən/', 'e', 'A violent, cruel, lawless, and brutal fellow; a swaggering street bully.', 'From OF "rufien" (pimp, scoundrel), from Italian "ruffiano."', '"A gang of drunken ruffians lurked in the shadow of the tavern archway."', 'Elizabethan police records'],
    ['Cutpurse', '/ˈkʌt.pɜːrs/', 'e', 'A pickpocket (literally one who cut purses made of leather tied to the girdle).', 'From "cut" + "purse." The precursor to the modern pickpocket.', '"A cutpurse of the empire and the rule, that from a shelf the precious diadem stole!"', 'Shakespeare, "Hamlet"'],
    ['Cozen', '/ˈkʌz.ən/', 'e', 'To trick, deceive, cheat, or defraud someone by artful pretenses.', 'Probably from Italian "cozzone" (horse-trader, known for sharp practices).', '"I am not easily cozened by smooth words and promises whispered in corners."', 'Shakespeare, "Merry Wives of Windsor"'],
    ['Gull', '/ɡʌl/', 'e', 'A gullible person easily cheated or duped; to trick or dupe someone.', 'From "gull" (young bird, unfledged chick), which swallows anything offered.', '"O gull! O dolt! As ignorant as dirt! Thou hast done a deed worthy of shame."', 'Shakespeare, "Othello"'],
    ['Roisterer', '/ˈrɔɪ.stər.ər/', 'e', 'A noisy, swaggering, boisterous reveller who drinks and brawls through the streets.', 'From French "rustre" (clown, boor, from Latin "rusticus" rustic).', '"A band of midnight roisterers woke the entire neighborhood with their rowdy singing."', 'Jacobean city comedies'],
    ['Malapert', '/ˌmæl.əˈpɜːrt/', 'e', 'Impudent, saucy, boldly disrespectful in speech.', 'From OF "malapert" — unskillful, foolish ("mal-" bad + "apert" open, clever).', '"Peace, thou malapert boy! Knowest thou to whom thou speakest?"', 'Shakespeare, "Twelfth Night"'],
    ['Pickthank', '/ˈpɪk.θæŋk/', 'e', 'A sycophant, flatterer, or talebearer who seeks favor by currying favor or informing.', 'From "pick" + "thank" (one who picks up thanks by obsequious fawning).', '"Smiling pickthanks and base newsmongers had poisoned the prince\'s mind."', 'Shakespeare, "Henry IV, Part 1"'],
    ['Slug-a-bed', '/ˈslʌɡ.ə.bɛd/', 'e', 'A lazy person who stays in bed late; a late riser.', 'From "slug" (slow, sluggish creature) + "in bed."', '"Why, lamb! Why, lady! Fie, you slug-a-bed! Why, love, I say! Madam! Sweetheart!"', 'Shakespeare, "Romeo and Juliet"'],
    ['Bedlamite', '/ˈbɛd.ləm.aɪt/', 'e', 'A madman; an inmate or discharged patient of London\'s Bethlem Hospital.', 'From "Bedlam" (popular contraction of the Hospital of St. Mary of Bethlehem).', '"He ran through the market shouting gibberish like an escaped bedlamite."', 'Jacobean accounts'],
    ['Mooncalf', '/ˈmuːn.kɑːf/', 'e', 'A congenital idiot, simpleton; originally a monstrous birth thought caused by the moon.', 'From "moon" (lunar influence) + "calf" (offspring).', '"I shall laugh myself to death at this puppy-headed monster. A most scurvy monster! A mooncalf!"', 'Shakespeare, "The Tempest"'],
    ['Urchin', '/ˈɜːr.tʃɪn/', 'e', 'Originally a hedgehog; later a mischievous, ragged street child or a fairy.', 'From Anglo-French "herichun," from Latin "ericius" (hedgehog).', '"Urchins shall, for that vast of night that they may work, all exercise on thee."', 'Shakespeare, "The Tempest"'],
    ['Bantling', '/ˈbænt.lɪŋ/', 'e', 'A young or small child; an infant, often one born out of wedlock.', 'Probably from German "Bänkling" (bench-child, child begotten on a bench).', '"The poor mother held her whimpering bantling close against the winter wind."', 'Victorian novels'],
    ['Paramour', '/ˈpær.ə.mʊər/', 'e', 'An illicit lover, mistress, or secret sweetheart of a married person.', 'From Anglo-French "par amour" — through love (Latin "per amorem").', '"He kept a fair paramour in a cottage secluded within the forest."', 'Chaucer, "Reeve\'s Tale"'],
    ['Inamorata', '/ɪˌnæm.əˈrɑː.tə/', 'e', 'A woman with whom someone is deeply in love; a female sweetheart.', 'From Italian "innamorata," feminine past participle of "innamorare" (to fall in love).', '"The poet composed fifty sonnets dedicated solely to his divine inamorata."', 'Elizabethan lyric collections'],
    ['Farthingale', '/ˈfɑːr.ðɪŋ.ɡeɪl/', 'e', 'A hooped petticoat or framework used to extend women\'s skirts out at the hips.', 'From Spanish "verdugado" (hooped skirt), from "verdugo" (green sapling, shoot).', '"Her wheel farthingale was so monstrously wide that she could scarce pass the door."', 'Jacobean satire'],
    ['Stomacher', '/ˈstʌm.ə.tʃər/', 'e', 'A decorative V-shaped panel filling the front opening of a lady\'s bodice or gown.', 'From "stomach" + suffix "-er." Often richly embroidered with pearls and gold thread.', '"The queen wore a black velvet gown with a stomacher stiffened with thousands of pearls."', 'Inventories of Elizabeth I'],
    ['Doublet', '/ˈdʌb.lɪt/', 'e', 'A man\'s snug-fitting padded jacket, fashionable from the 14th to 17th centuries.', 'From OF "doublet," something doubled (two layers of linen stuffed with wool).', '"What a piece of work is man! In doublet and hose, walking like an emperor."', 'Shakespeare, "Hamlet"'],
    ['Jerkin', '/ˈdʒɜːr.kɪn/', 'e', 'A close-fitting collarless jacket, often of leather, worn over the doublet.', 'Of obscure origin; possibly from Dutch "jurk" (frock, dress).', '"A buff leather jerkin that has turned three sword-cuts and never let in water."', 'Shakespeare, "Henry IV"'],
    ['Codpiece', '/ˈkɒd.piːs/', 'e', 'A pouch or flap covering the front fastening in men\'s breeches during the 15th-16th centuries.', 'From ME "cod" (bag, scrotum, husk) + "piece."', '"Why, what an unthrift in the world was he to buy so wide a pair of breeches with a monstrous codpiece!"', 'Rabelais / Elizabethan satires'],
    ['Baldric', '/ˈbɔːl.drɪk/', 'e', 'A belt or sash worn over one shoulder and across the chest to carry a sword, bugle, or shield.', 'From OF "baudrei," of Germanic origin (OHG "balderich").', '"Athwart his breast a baldric hung of green samite, sparkling with chrysolites."', 'Tennyson, "Idylls of the King"'],
    ['Periwig', '/ˈpɛr.ɪ.wɪɡ/', 'e', 'A fashionable artificial wig worn by men in the 17th and 18th centuries.', 'Alteration of French "perruque." Later shortened to "wig."', '"He adjusted his powdered periwig in the gilded looking-glass before entering the drawing-room."', 'Congreve, "The Way of the World"'],
    ['Pomander', '/pɒmˈæn.dər/', 'e', 'A perforated ball containing ambergris, cloves, and perfumes carried as a charm against pestilence.', 'From OF "pomme d\'ambre" — apple of ambergris.', '"He held a pomander of silver filigree to his nose as he passed the open sewers of the city."', 'Elizabethan plague tracts'],
    ['Chopine', '/tʃəˈpiːn/', 'e', 'A platform shoe with an enormous cork sole worn by Venetian and Elizabethan women to keep above mud.', 'From Spanish "chapín" (clog), echoic of the clacking sound made when walking.', '"Your ladyship is nearer to heaven than when I saw you last, by the altitude of a chopine!"', 'Shakespeare, "Hamlet"'],
    ['Pattens', '/ˈpæt.ənz/', 'e', 'Wooden or iron overshoes strapped under boots to lift the feet above street mud and refuse.', 'From OF "patin" (clog), related to Greek "pateis" (to tread).', '"The ladies clicked and clattered down the cobbled alley on their iron pattens."', 'Jane Austen, "Persuasion"'],

    // --- VICTORIAN, REGENCY & ECCENTRIC WORDS (t) ---
    ['Pettifogger', '/ˈpɛt.iˌfɒɡ.ər/', 't', 'An unscrupulous, disreputable lawyer who deals in petty cases with sly trickery.', 'From "petty" (small) + obsolete "fogger" (schemer, from the Fugger banking family).', '"Mr. Vholes was not a pettifogger, but he pursued his client\'s bill of costs with relentless vigor."', 'Dickens, "Bleak House"'],
    ['Blatherskite', '/ˈblæð.ərˌskaɪt/', 't', 'A talkative, foolish person who speaks nonsense loudly and at endless length.', 'From Scottish "blather" (to talk nonsense) + "skate" (contemptible person).', '"Don\'t listen to that old blatherskite; he knows no more of finance than a newborn infant."', 'Victorian parliamentary debates'],
    ['Skulduggery', '/skʌlˈdʌɡ.ər.i/', 't', 'Underhanded, deceitful, or unscrupulous behavior or political scheming.', 'From Scottish "sculduddery" (fornication, gross obscenity), later shifted to trickery.', '"The entire election was tainted by municipal skulduggery and bribery of voters."', 'Victorian newspapers'],
    ['Bamboozle', '/bæmˈbuː.zəl/', 't', 'To deceive, perplex, confound, or practice trickery upon someone.', 'Early 18th-century slang of unknown origin; recorded in Swift\'s list of vulgar neologisms.', '"He completely bamboozled the magistrate with a fabricated alibi and false witnesses."', 'Victorian court records'],
    ['Flummox', '/ˈflʌm.əks/', 't', 'To bewilder, confound, confuse utterly; to throw into perplexed helplessness.', 'Probably dialectal English (Herefordshire/Gloucestershire "flummock" to agitate, defeat).', '"The sudden turn of events utterly flummoxed the senior partners of the bank."', 'Dickens, "Pickwick Papers"'],
    ['Discombobulate', '/ˌdɪs.kəmˈbɒb.jʊ.leɪt/', 't', 'To upset, confuse, disconcert, or throw into complete disorder.', 'American humorous mock-Latin slang from the 1830s, popularized in Victorian England.', '"The loud crash of the tea-tray discombobulated the entire afternoon gathering."', 'Humorous Victorian sketches'],
    ['Collywobbles', '/ˈkɒl.iˌwɒb.əlz/', 't', 'Bellyache, stomach distress, or intense nervousness accompanied by fluttering guts.', 'From "colic" (belly pain) + "wobble" (shaky movement).', '"I confess that the prospect of public speaking gives me an awful attack of the collywobbles."', 'Victorian memoirs'],
    ['Lollygag', '/ˈlɒl.i.ɡæɡ/', 't', 'To dawdle, fool around, waste time, or loiter aimlessly.', 'American/British dialect slang from the 1860s.', '"Stop lollygagging by the bookshop window and deliver this parcel immediately!"', 'Victorian children\'s stories'],
    ['Gallivant', '/ˈɡæl.ɪ.vænt/', 't', 'To go about in search of amusement or pleasure, especially in flirtatious company.', 'Alteration of "gallant" (to act the chivalrous gallant / court ladies).', '"Her son was forever gallivanting across the continent while his debts accumulated at home."', 'Thackeray, "Vanity Fair"'],
    ['Folderol', '/ˈfɒl.də.rɒl/', 't', 'Nonsense; foolish talk or ideas; useless or showy trifles.', 'From the nonsensical refrain of old songs: "fol-de-rol-de-ray."', '"I have no patience for all this modern folderol and scientific nonsense!"', 'Victorian drawing-room comedies'],
    ['Poppycock', '/ˈpɒp.i.kɒk/', 't', 'Senseless talk, complete rubbish, nonsense.', 'From Dutch dialect "poppekak" — soft doll-dung ("pop" doll + "kak" excrement).', '"Pure unadulterated poppycock! That man hasn\'t spoken a grain of truth all year."', 'Victorian political journalism'],
    ['Rigmarole', '/ˈrɪɡ.mə.roʊl/', 't', 'A lengthy, complicated, confused, and nonsensical procedure or rambling story.', 'Alteration of "Ragman roll" (a 13th-century roll of Scottish nobility\'s homage to Edward I).', '"We had to go through a preposterous bureaucratic rigmarole merely to secure a passport."', 'Victorian travel memoirs'],
    ['Flummery', '/ˈflʌm.ər.i/', 't', 'Empty compliment, insincere flattery, nonsense; originally a bland Welsh oatmeal pudding.', 'From Welsh "llymru" (sour oatmeal jelly, porridge).', '"The prime minister\'s speech was nothing but rhetorical flummery, signifying nothing."', 'Victorian editorial essays'],
    ['Hornswoggle', '/ˈhɔːrnˌswɒɡ.əl/', 't', 'To cheat, bamboozle, hoax, or deceive someone cleverly.', '19th-century comic formation, popular in both Britain and the American frontier.', '"The clever auctioneer hornswoggled the gentleman into buying a gilded lead watch."', 'Victorian humorous periodicals'],
    ['Shenanigans', '/ʃəˈnæn.ɪ.ɡənz/', 't', 'Secret or dishonest activity, mischievous pranks, high-spirited trickery.', 'Probably from Irish "sionnachuighim" (I play the fox, play tricks, from "sionnach" fox).', '"There were too many nocturnal shenanigans going on beneath the headmaster\'s nose."', 'Public school memoirs'],
    ['Codswallop', '/ˈkɒdzˌwɒl.əp/', 't', 'Complete nonsense, rubbish. Often said to relate to Hiram Codd\'s patented soft-drink bottles.', 'Attributed to "Codd" (bottle maker) + "wallop" (slang for beer/drink). Meaning: fizzy rubbish.', '"What absolute codswallop! Do you expect a grown man to believe such a fairy-tale?"', 'British colloquial speech'],
    ['Taradiddle', '/ˌtær.əˈdɪd.əl/', 't', 'A petty lie, a fib; pretentious nonsense.', 'Probably related to "diddle" (to swindle, cheat) with playful reduplicative prefix.', '"Her recount of meeting the Queen was judged by all to be a brazen taradiddle."', 'Victorian domestic memoirs'],
    ['Absquatulate', '/æbˈskwɒtʃ.ʊ.leɪt/', 't', 'To decamp, sneak away hastily, run off, or abscond with money.', 'Humorous mock-Latin coinage of the 1830s: "ab-" (away) + "squat" + Latinate suffix.', '"The cashier absquatulated in the dead of night, taking forty thousand pounds with him."', 'Punch magazine, 1850'],
    ['Cattywampus', '/ˌkæt.iˈwɒm.pəs/', 't', 'Askew, awry, diagonally positioned, out of alignment.', 'Colloquial 19th-century coinage; variant of "catawampus."', '"The gale left the chimney-pots and garden fence looking completely cattywampus."', 'Victorian dialect stories'],
    ['Ballyhoo', '/ˈbæl.i.huː/', 't', 'Extravagant publicity or noisy promotional uproar; sensational hype.', 'Possibly from the Irish village Ballyhooly, famous for noisy faction fights.', '"Beneath all the theatrical ballyhoo lay a performance of third-rate caliber."', 'Theatrical memoirs'],
    ['Balderdash', '/ˈbɔːl.dər.dæʃ/', 't', 'Senseless talk, writing, or nonsense; originally a jumble of mixed liquors.', 'Early 17th-century term for a disordered mixture of drinks, later transferred to speech.', '"The attorney dismissed the witness\'s testimony as pure, unadulterated balderdash."', 'Dickens, "Nicholas Nickleby"'],
    ['Highfalutin', '/ˌhaɪ.fəˈluː.tɪn/', 't', 'Pompous, pretentious, bombastic, high-flown in language or manners.', 'Probably from "high-fluting" (playing high notes on a flute / whistling high).', '"She gave herself highfalutin airs, pretending her father had been a baronet."', 'George Eliot, "Middlemarch"'],
    ['Cantankerous', '/kænˈtæŋ.kər.əs/', 't', 'Bad-tempered, argumentative, uncooperative, stubbornly quarrelsome.', 'Probably a blend of ME "contek" (strife, contention) + "rancorous."', '"The old sea-captain was a cantankerous soul who quarreled with every cabin boy."', 'Victorian seafaring tales'],
    ['Persnickety', '/pərˈsnɪk.ɪ.ti/', 't', 'Placing excessive emphasis on trivial details; fussy, fastidious, finicky.', 'Scottish origin ("pernickety," late 18th century).', '"The head clerk was so persnickety that he rejected letters for a single blotted comma."', 'Victorian office reminiscences'],
    ['Curmudgeon', '/kərˈmʌdʒ.ən/', 't', 'A bad-tempered, crusty, ill-natured person, especially an old man.', 'Unknown origin; Dr. Samuel Johnson amusingly suggested French "cœur méchant" (wicked heart).', '"The landlord was an old curmudgeon who turned off the gas lamps at precisely nine."', 'Dickens, "A Christmas Carol"'],
    ['Scalawag', '/ˈskæl.ə.wæɡ/', 't', 'A scamp, rascal, good-for-nothing rogue, mischievous person.', 'Originally Scalloway in the Shetland Islands (noted for diminutive cattle).', '"That young scalawag has been stealing apples from the parsonage orchard again!"', 'Victorian rural tales'],
    ['Sluggard', '/ˈslʌɡ.ərd/', 'm', 'A habitually lazy, sluggish person who avoids labor.', 'From ME "slugge" (lazy person) + pejorative suffix "-ard."', '"Go to the ant, thou sluggard; consider her ways, and be wise."', 'King James Bible, Proverbs 6:6'],
    ['Recreant', '/ˈrɛk.ri.ənt/', 'm', 'Cowardly, unfaithful to a pledge, craven; a traitor to his oath.', 'From OF "recreant" (yielding, crying mercy), from Latin "recredere" (to yield belief).', '"Thou recreant knight! Thou hast stained the honor of the Round Table forever!"', 'Malory, "Le Morte d\'Arthur"'],
    ['Nincompoop', '/ˈnɪŋ.kəm.puːp/', 't', 'A foolish, stupid, or silly person; a simpleton.', 'Recorded since the 1670s; often fancifully derived from Latin "non compos mentis."', '"Only an absolute nincompoop would venture onto the frozen tarn in early spring."', 'Victorian school stories'],
    ['Dandy', '/ˈdæn.di/', 't', 'A man devoted to elegance and refined fastidiousness in dress and manners (a beau).', 'Of uncertain origin; associated with the Scottish border and the song "Yankee Doodle."', '"Beau Brummell was the supreme dandy of the Regency, setting the mode for all London."', 'Thackeray, "The Book of Snobs"'],
    ['Bluestocking', '/ˈbluːˌstɒk.ɪŋ/', 't', 'An educated, intellectual, or literary woman (often used with patronizing irony).', 'From the Blue Stocking Society (c. 1750), where Benjamin Stillingfleet wore blue worsted stockings.', '"She was regarded as a formidable bluestocking, reading Greek before breakfast."', 'George Eliot'],
    ['Dowager', '/ˈdaʊ.ə.dʒər/', 't', 'A widow holding property or a title derived from her deceased husband; a stately elder woman.', 'From Anglo-Norman "douagere," from "doue" (dower, Latin "dotare").', '"The Dowager Duchess entered the ballroom with the majestic tread of an empress."', 'Jane Austen, "Pride and Prejudice"'],
    ['Bedizen', '/bɪˈdaɪ.zən/', 't', 'To dress up or decorate gaudily, showily, or in vulgar bad taste.', 'From prefix "be-" + obsolete "dizen" (to dress a distaff with flax, dress up).', '"She appeared at church bedizened with yellow ribbons, false pearls, and dyed ostrich plumes."', 'Victorian novels'],
    ['Furbelow', '/ˈfɜːr.bə.loʊ/', 't', 'A gathered frill, flounce, or ornamental ruffle on a woman\'s petticoat or dress.', 'From French "falbala" (flounce, ruffle) via Italian "falfala."', '"A whirlwind of silk and furbelows descended the grand staircase."', 'Thackeray, "Vanity Fair"'],
    ['Crinoline', '/ˈkrɪn.ə.lɪn/', 't', 'A stiffened petticoat or skirt structure made of horsehair fabric or steel hoops.', 'From French "crinoline," from Latin "crinis" (horsehair) + "linum" (linen).', '"The ladies in their ballooning crinolines could barely fit through the pews."', 'Victorian satiric sketches'],
    ['Bustle', '/ˈbʌs.əl/', 't', 'A padded framework or cushion worn under the back of a woman\'s skirt to puff it out.', 'Probably from "bustle" (noisy activity, puffed-up fullness).', '"The fashionable bustle of 1885 gave ladies the silhouette of a proud pouter pigeon."', 'Fashion history of Victorian England'],
    ['Reticule', '/ˈrɛt.ɪ.kjuːl/', 't', 'A woman\'s small handbag or drawstring purse, often carried on the arm.', 'From French "réticule," from Latin "reticulum" (little network, net bag).', '"She opened her beaded reticule and withdrew a lace handkerchief scented with lavender."', 'Jane Austen, "Emma"'],
    ['Pince-nez', '/ˈpæns.neɪ/', 't', 'Eyeglasses without sidepieces, clipped onto the bridge of the nose by a spring.', 'From French "pincer" (to pinch) + "nez" (nose) — literally "pinch-nose."', '"The inspector adjusted his pince-nez and studied the smudged footprints in the snow."', 'Conan Doyle, "Sherlock Holmes"'],
    ['Lorgnette', '/lɔːrˈnjɛt/', 't', 'A pair of spectacles or opera glasses mounted on a long ornamental handle.', 'From French "lorgner" (to squint at, look sidelong).', '"The countess raised her gold-handled lorgnette and surveyed the theater box."', 'Victorian society novels'],
    ['Antimacassar', '/ˌæn.ti.məˈkæs.ər/', 't', 'A decorative cloth placed over the back of armchairs to prevent staining from Macassar hair-oil.', 'From "anti-" (against) + "Macassar" oil (a popular Victorian hair pomade from Indonesia).', '"Every armchair in the parlor was draped with an intricately crocheted white antimacassar."', 'Victorian home journals'],
    ['Spittoon', '/spɪˈtuːn/', 't', 'A metal or ceramic receptacle for spit, common in public places and smoking-rooms.', 'From "spit" + augmentative suffix "-oon."', '"A polished brass spittoon stood by the legs of the billiard table."', 'Victorian club records'],
    ['Cuspidor', '/ˈkʌs.pɪ.dɔːr/', 't', 'Another term for a spittoon, used in polite or hotel contexts.', 'From Portuguese "cuspidor" (spitter, from "cuspir" to spit, Latin "conspuere").', '"The porter emptied the porcelain cuspidors each morning before the guests came down."', 'Hotel management records of the 1870s'],
    ['Chiffonier', '/ˌʃɪf.əˈnɪər/', 't', 'A tall, elegant chest of drawers, often with a mirrored back or lower cupboard.', 'From French "chiffonnier" (rag-picker), from "chiffon" (rag, scraps of cloth).', '"A silver candlestick and a bronze clock stood atop the rosewood chiffonier."', 'Victorian interior descriptions'],
    ['Mudlark', '/ˈmʌd.lɑːrk/', 't', 'A street child or scavenger who searched the tidal mud of the Thames for scrap iron, rope, and coal.', 'From "mud" + "lark" (ironic contrast between the bird and the dirty scavenger).', '"Poor little mudlarks, wading knee-deep in the freezing ooze beneath London Bridge."', 'Henry Mayhew, "London Labour and the London Poor"'],
    ['Knocker-up', '/ˈnɒk.ər.ʌp/', 't', 'A person employed to wake sleeping factory workers by tapping on bedroom windows with a long pole.', 'From the verb "to knock up" (to wake someone by knocking).', '"The knocker-up was already tapping on the upper panes as dawn broke over Manchester."', 'Industrial histories of northern England'],
    ['Costermonger', '/ˈkɒs.tərˌmʌŋ.ɡər/', 't', 'A street seller of fruit, vegetables, and fish from a barrow or donkey-cart.', 'From "costard" (a large variety of apple) + "monger" (dealer, trader, OE "mangere").', '"The costermongers shouted their wares through the foggy alleys of Covent Garden."', 'Mayhew, "London Labour"'],
    ['Haberdasher', '/ˈhæb.ərˌdæʃ.ər/', 't', 'A dealer in small sewing notions (threads, ribbons, buttons, needles); in US, men\'s clothes.', 'From Anglo-Norman "haberdash" (small wares, notions).', '"She bought two yards of matching silk ribbon at the haberdasher\'s shop in the High Street."', 'Victorian domestic tales'],

    // --- ARCHAIC VERBS & MENTAL STATES (m / e) ---
    ['Beseech', '/bɪˈsiːtʃ/', 'm', 'To ask someone urgently and fervently to do something; to implore.', 'From OE "bisēcan" — to seek out, beg ("be-" + "sēcan" seek).', '"I beseech you, hear me speak before judgment is pronounced."', 'Shakespeare, "Merchant of Venice"'],
    ['Entreat', '/ɪnˈtriːt/', 'm', 'To ask earnestly; to beg; to treat or manage.', 'From Anglo-Norman "entreter" — to deal with, handle (Latin "intractare").', '"I entreat your honor to have patience with an old servant."', 'Shakespeare, "Measure for Measure"'],
    ['Vouchsafe', '/ˌvaʊtʃˈseɪf/', 'm', 'To grant or give graciously, as a favor from a superior; to deign.', 'From "vouch" + "safe" (to warrant as safe, guarantee protection).', '"Vouchsafe, O Lord, to keep us this day without sin."', 'The Book of Common Prayer, Te Deum'],
    ['Descry', '/dɪˈskraɪ/', 'm', 'To catch sight of, discern from a distance, or detect by careful looking.', 'From OF "descrier" — to proclaim, shout out upon sighting something.', '"From the maintop, the lookout descried the white cliffs of Dover on the horizon."', 'Hakluyt, "Voyages"'],
    ['Espy', '/ɪˈspaɪ/', 'm', 'To catch sight of; to glimpse something hidden or distant.', 'From OF "espiier" — to watch, spy (from Germanic *spehon).', '"He espied his enemy advancing through the mist between the trees."', 'Malory, "Le Morte d\'Arthur"'],
    ['Hearken', '/ˈhɑːr.kən/', 'm', 'To listen carefully; to pay heed; to give obedient ear.', 'From OE "heorcnian" — to listen with attention.', '"Hearken unto my voice, O Lord, when I cry unto Thee."', 'King James Bible, Psalms'],
    ['Tarry', '/ˈtær.i/', 'm', 'To delay, linger, remain in a place; to wait for someone.', 'From ME "tarien" — to delay, hesitate, hinder.', '"Tarry awhile, lean knight; the feast is not yet begun."', 'Chivalric romances'],
    ['Wend', '/wɛnd/', 'm', 'To go, travel, proceed in a specified direction. "To wend one\'s way."', 'From OE "wendan" — to turn, go. The past tense "went" became the past of "go"!', '"The pilgrims wended their weary way toward Canterbury Cathedral."', 'Chaucerian tales'],
    ['Quaff', '/kwɒf/', 'e', 'To drink heartily, deeply, and with evident relish.', 'Probably of echoic/dialectal origin; possibly related to Low German "quassen" (to overeat).', '"They quaffed great tankards of spiced ale until the small hours of the morning."', 'Scott, "Ivanhoe"'],
    ['Tipple', '/ˈtɪp.əl/', 'e', 'To drink intoxicating liquor habitually or in small sips.', 'Of uncertain origin; perhaps related to dialectal "tip" (to tilt the cup).', '"The parish clerk was known to tipple a quiet glass of port at the Green Dragon."', 'Victorian village sketches'],
    ['Languish', '/ˈlæŋ.ɡwɪʃ/', 'm', 'To grow weak, faint, or feeble; to suffer neglect or pining love in sorrow.', 'From OF "languir" (to languish, Latin "languere").', '"In the deep dungeon, the captive knight languished for seven long summers."', 'Medieval romances'],
    ['Bewail', '/bɪˈweɪl/', 'm', 'To express deep regret, sorrow, or grief over; to lament loudly.', 'From ME "bewailen" — "be-" + "wail" (from Old Norse "væla" to lament).', '"She bewept her dead lord and bewailed the fall of her ancient house."', 'Chaucer, "Troilus and Criseyde"'],
    ['Repine', '/rɪˈpaɪn/', 'e', 'To feel or express discontent, fretfulness, or melancholy dejection.', 'From "re-" + obsolete "pine" (to suffer, grieve, from OE "pīnian").', '"He bore his misfortunes without a murmur, never repining against Providence."', 'Jane Austen, "Sense and Sensibility"'],
    ['Blench', '/blɛntʃ/', 'm', 'To flinch, shrink back, or turn pale from fear, pain, or astonishment.', 'From OE "blencan" — to deceive, flinch. Cognate with "blink."', '"If he but blench, I know my course!"', 'Shakespeare, "Hamlet"'],
    ['Quail', '/kweɪl/', 'm', 'To feel fear or apprehension; to cower, shrink, or lose courage.', 'From ME "qualen" — to die, sicken (from OE "cwelan" to perish).', '"The stoutest hearts quailed before the terrible thunder of the bombardment."', 'Military histories'],
    ['Fawn', '/fɔːn/', 'm', 'To court favor by groveling, flattering, and servile cringing (like a dog).', 'From OE "fagnian" — to rejoice, be glad (from "fægen" glad).', '"He hated those fawning courtiers who changed their smiles with every wind of fortune."', 'Shakespeare, "Julius Caesar"'],
    ['Upbraid', '/ʌpˈbreɪd/', 'm', 'To reproach severely, find fault with, or scold sharply for a wrongdoing.', 'From OE "upbregdan" — to lift up, brandish, bring forward as a reproach.', '"She upbraided him for his reckless squandering of the family patrimony."', 'Milton, "Paradise Lost"'],
    ['Traduce', '/trəˈdjuːs/', 'e', 'To slander, speak falsely and maliciously of; to expose to public shame.', 'From Latin "traducere" — to lead across, display to ridicule, defame.', '"I will not suffer my good name to be traduced by anonymous scribblers in the gazette."', 'Elizabethan letters'],
    ['Vituperate', '/vaɪˈtjuː.pə.reɪt/', 't', 'To blame, insult, or criticize in a passionate and abusive manner.', 'From Latin "vituperare" — to blame, find fault ("vitium" fault + "parare" prepare).', '"The editor vituperated his political rivals in columns of unbridled invective."', 'Victorian journalism'],
    ['Flout', '/flaʊt/', 'e', 'To openly disregard, mock, insult, or treat with contemptuous disdain.', 'Probably from Middle Dutch "fluiten" (to play the flute, whistle at in mockery).', '"To flout at Fortune\'s wheel and mock the decrees of the parliament."', 'Shakespeare, "As You Like It"'],

    // --- ARCHAIC ADJECTIVES & NATURE (m / e / t) ---
    ['Craven', '/ˈkreɪ.vən/', 'm', 'Contemptibly cowardly, fainthearted; a cowardly person.', 'From Anglo-Norman "cravant" (vanquished, crying mercy), from Latin "crepare" (to crack).', '"A craven knight who fled the field while his liege lord fought surrounded."', 'Scott, "Ivanhoe"'],
    ['Debonair', '/ˌdɛb.əˈnɛər/', 'm', 'Gentle, gracious, courteous, charming, confident, and dashing in manners.', 'From OF "debonaire" — of good stock, gentle ("de bon aire" of good lineage).', '"A knight of noble bearing, debonair and courteous to all women and pilgrims."', 'Chaucer, "Book of the Duchess"'],
    ['Blithe', '/blaɪð/', 'm', 'Joyous, merry, cheerful, carefree, lighthearted.', 'From OE "blīþe" — happy, joyous, friendly. Cognate with German "blöde" (anciently kind).', '"Hail to thee, blithe Spirit! Bird thou never wert..."', 'Shelley, "To a Skylark"'],
    ['Winsome', '/ˈwɪn.səm/', 'm', 'Attractive, charming, pleasing, endearing, sweetly winning.', 'From OE "wynsum" — delightful, pleasant (from "wyn" joy, bliss + "-some").', '"Her winsome smile and gentle voice softened the hardest hearts in the assembly."', 'Victorian romances'],
    ['Pulchritudinous', '/ˌpʌl.krɪˈtjuː.dɪ.nəs/', 't', 'Characterized by breathtaking physical beauty and comeliness.', 'From Latin "pulchritudo" (beauty), from "pulcher" (beautiful).', '"The heroine was depicted as the most pulchritudinous damsel in the three shires."', 'Humorous Victorian periodicals'],
    ['Cadaverous', '/kəˈdæv.ər.əs/', 't', 'Resembling a corpse; pale, gaunt, haggard, emaciated.', 'From Latin "cadaverosus," from "cadaver" (corpse, dead body).', '"His cadaverous face and hollow burning eyes gave him the look of an escaped phantom."', 'Poe, "The Fall of the House of Usher"'],
    ['Saturnine', '/ˈsæt.ər.naɪn/', 'e', 'Gloomy, dark, morose, cold, and slow in temperament (influenced by the planet Saturn).', 'From Medieval Latin "Saturninus" — born under the influence of the cold planet Saturn.', '"He had a saturnine complexion and rarely smiled even at the wittiest jest."', 'Bronte, "Wuthering Heights"'],
    ['Churlish', '/ˈtʃɜːr.lɪʃ/', 'm', 'Rude, surly, ungracious, boorish, ill-mannered.', 'From OE "ceorlic" — rustic, characteristic of a peasant/churl.', '"It would be churlish in the extreme to refuse the hospitality of an ancient host."', 'Stevenson, "Treasure Island"'],
    ['Coppice', '/ˈkɒp.ɪs/', 'm', 'A dense area of woodland consisting of small trees periodically cut back to ground level.', 'From OF "copeiz" (cut wood), from Medieval Latin "colpare" (to cut). Shortened to "copse."', '"A pheasant rose with a loud clatter of wings from the birch coppice."', 'Thomas Hardy, "The Woodlanders"'],
    ['Dingle', '/ˈdɪŋ.ɡəl/', 'm', 'A deep, narrow, secluded wooded valley or dell.', 'Of uncertain ME origin; possibly related to "dimple" or dialectal "ding" (hollow).', '"They rested their horses in a cool, shady dingle beside a whispering brook."', 'Tolkien, "The Lord of the Rings"'],
    ['Fell', '/fɛl/', 'm', 'A high, barren, rocky moor or mountain upland in northern England and Scotland.', 'From Old Norse "fjall" / "fell" (mountain, rocky hill).', '"The sheep roamed the lonely windy fells under a brooding autumn sky."', 'Emily Bronte, "Wuthering Heights"'],
    ['Tarn', '/tɑːrn/', 'm', 'A small mountain lake or pool, especially one formed in a glacial cirque.', 'From Old Norse "tjörn" (small mountain lake, pond).', '"The dark, fathomless waters of the tarn reflected the towering granite crags."', 'Wordsworth, "The Excursion"'],
    ['Welkin', '/ˈwɛl.kɪn/', 'm', 'The sky, the upper heavens, the vault of the firmament.', 'From OE "wolcen" — cloud. Cognate with German "Wolke" (cloud).', '"The shouts of the victorious host made the welkin ring."', 'Shakespeare, "Merry Wives of Windsor"'],
    ['Firmament', '/ˈfɜːr.mə.mənt/', 'm', 'The vast expanse of the sky or heavens, regarded as a solid celestial dome.', 'From Latin "firmamentum" (strengthening, foundation, expanse), from "firmus."', '"The heavens declare the glory of God; and the firmament showeth His handiwork."', 'King James Bible, Psalm 19:1'],
    ['Gloaming', '/ˈɡloʊ.mɪŋ/', 'm', 'The twilight, dusk, evening twilight after sunset.', 'From OE "glōmung" (twilight), from "glōm" (gloom, twilight).', '"In the purple gloaming, the bats began their silent, erratic flight over the pond."', 'Scottish ballads'],
    ['Eventide', '/ˈiː.vən.taɪd/', 'm', 'The time of evening; twilight.', 'From OE "ǣfentīd" — evening + time/tide.', '"At eventide the church bells chimed across the misty meadows."', 'English pastoral poetry']
];

